/**
 * Initialize the input data using Halide Funcs, mirroring the original C code.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     x1[i]  = (DATA_TYPE) (i % n) / n;
 *     x2[i]  = (DATA_TYPE) ((i + 1) % n) / n;
 *     y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
 *     y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
 *     for (j = 0; j < n; j++)
 *       A[i][j] = (DATA_TYPE) (i*j % n) / n;
 *   }
 *
 * Mapping to Halide:
 *   - 1D arrays x1, x2, y1, y2: Buffer<num_t,1> of size n, indexed as buf(i)
 *   - 2D array A[i][j]: Buffer<num_t,2> with shape (n, n), indexed as A(j, i)
 *     (first dim is column j, second dim is row i), following the gemm example.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 1> x1,
                       Halide::Buffer<num_t, 1> x2,
                       Halide::Buffer<num_t, 1> y1,
                       Halide::Buffer<num_t, 1> y2,
                       Halide::Buffer<num_t, 2> A) {
