    Func init_x1("init_x1"), init_x2("init_x2");
    Func init_y1("init_y1"), init_y2("init_y2");
    Func init_A("init_A");

    // We'll use n as an Expr where needed.
    Expr n_expr = n;

    // 1D initializations
    init_x1(i) = cast<num_t>(i % n_expr) / cast<int>(n_expr);
    init_x2(i) = cast<num_t>((i + 1) % n_expr) / cast<int>(n_expr);
    init_y1(i) = cast<num_t>((i + 3) % n_expr) / cast<int>(n_expr);
    init_y2(i) = cast<num_t>((i + 4) % n_expr) / cast<int>(n_expr);

    // 2D initialization for A:
    // C: A[i][j] = (i*j % n) / n;
    // Buffer: A(j, i) stores A[i][j].
    init_A(j, i) = cast<num_t>((i * j) % n_expr) / cast<int>(n_expr);

    // Realize into the provided buffers.
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y1);
    init_y2.realize(y2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from PolyBench/MVT definitions)
    int n = N;

    // Allocate data buffers.
    // For 2D A[i][j], we follow the same convention as in gemm.cpp:
    //   C array A[i][j]  -> Halide buffer A(j, i)
    Halide::Buffer<num_t, 2> A(n, n);   // (x = j, y = i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y1(n);
    Halide::Buffer<num_t, 1> y2(n);

    // Initialize arrays.
    init_array(n, x1, x2, y1, y2, A);

    // Set up ImageParams to represent the inputs to the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y1);
    y2_param.set(y2);

    // Vars and reduction domain.
    Var i("i");
    // The inner loop in C is j from 0 to n-1. We use the extent of A's first
    // dimension to define the reduction domain.
    RDom j(0, A.dim(0).extent(), "j");

    // Define the two main computations, mirroring kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_N; i++)
    //   for (j = 0; j < _PB_N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    //
    // for (i = 0; i < _PB_N; i++)
    //   for (j = 0; j < _PB_N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Remember: buffer A(j, i) corresponds to C's A[i][j].

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First set of loops: x1 update
    // Initialize with the original x1, then accumulate over j:
    // mvt_x1(i) = x1[i];
    // mvt_x1(i) += A[i][j] * y_1[j];
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(j, i) * y1_param(j);  // A[i][j] -> A_param(j, i)

    // Second set of loops: x2 update
    // Initialize with the original x2, then accumulate over j:
    // mvt_x2(i) = x2[i];
    // mvt_x2(i) += A[j][i] * y_2[j];
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, j) * y2_param(j);  // A[j][i] -> A_param(i, j)

    // Simple root-level schedules for both vectors.
    mvt_x1.compute_root();
    mvt_x2.compute_root();

    // Compile the kernels to machine code.
    mvt_x1.compile_jit();
    mvt_x2.compile_jit();

    // Measure the execution time of the Halide kernels (similar to PolyBench timing
    // which only measures the kernel, not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernels: results are written back into x1 and x2 buffers.
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the results (similar to print_array in the C version),
    // mainly to avoid dead-code elimination in some toolchains.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
