 * Halide version of init_array from mvt.c
 *
 * C prototype:
 *   void init_array(int n,
 *                   DATA_TYPE x1[n],
 *                   DATA_TYPE x2[n],
 *                   DATA_TYPE y_1[n],
 *                   DATA_TYPE y_2[n],
 *                   DATA_TYPE A[n][n]);
 */
static void init_array(int n,
                       Buffer<num_t, 1> x1,
                       Buffer<num_t, 1> x2,
                       Buffer<num_t, 1> y_1,
                       Buffer<num_t, 1> y_2,
                       Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    Func init_x1("init_x1"), init_x2("init_x2");
    Func init_y1("init_y1"), init_y2("init_y2");
    Func init_A("init_A");

    // In C:
    //   x1[i] = (DATA_TYPE)(i % n) / n;
    //   x2[i] = (DATA_TYPE)((i + 1) % n) / n;
    //   y_1[i] = (DATA_TYPE)((i + 3) % n) / n;
    //   y_2[i] = (DATA_TYPE)((i + 4) % n) / n;
    init_x1(i) = cast<num_t>(i % n) / cast<int>(n);
    init_x2(i) = cast<num_t>((i + 1) % n) / cast<int>(n);
    init_y1(i) = cast<num_t>((i + 3) % n) / cast<int>(n);
    init_y2(i) = cast<num_t>((i + 4) % n) / cast<int>(n);

    // In C:
    //   A[i][j] = (DATA_TYPE)(i * j % n) / n;
    //
    // We store A as Buffer(n, n) and access A(j, i) to correspond to A[i][j].
    init_A(j, i) = cast<num_t>(((i * j) % n)) / cast<int>(n);

    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[n][n];
    //   DATA_TYPE x1[n], x2[n], y_1[n], y_2[n];
    //
    // For A[i][j], we use A(j, i) in Halide (first dimension is the column j,
    // second dimension is the row i).
    Buffer<num_t, 2> A(n, n);
    Buffer<num_t, 1> x1(n), x2(n), y_1(n), y_2(n);

    // Initialize data.
    init_array(n, x1, x2, y_1, y_2, A);

    // ImageParams to pass data into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Vars and reduction domain.
    Var i("i");
    // A_param.dim(0) is the j-dimension (columns).
    RDom j(0, A_param.dim(0).extent(), "j");

    // Main computational kernels, corresponding to kernel_mvt:
    //
    // C code:
    //   for (i = 0; i < N; i++)
    //     for (j = 0; j < N; j++)
    //       x1[i] = x1[i] + A[i][j] * y_1[j];
    //
    //   for (i = 0; i < N; i++)
    //     for (j = 0; j < N; j++)
    //       x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // In Halide we treat x1 and x2 as reductions over j.

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop: x1[i] = x1[i] + sum_j A[i][j] * y_1[j];
    // A[i][j] -> A_param(j, i); y_1[j] -> y1_param(j).
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(j, i) * y1_param(j);

    // Second loop: x2[i] = x2[i] + sum_j A[j][i] * y_2[j];
    // A[j][i] -> A_param(i, j); y_2[j] -> y2_param(j).
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, j) * y2_param(j);

    // We could add explicit scheduling here; for this simple 1D result
    // we rely on Halide's default schedule, which will compute mvt_x1
    // and mvt_x2 at the root when realized.

    // JIT-compile the pipelines.
    mvt_x1.compile_jit();
    mvt_x2.compile_jit();

    // Time the execution of both loops (together, as in the original kernel).
    auto start = std::chrono::high_resolution_clock::now();

    // Realize results back into the original buffers. As in the GEMM example,
    // we alias the ImageParams with the output buffers.
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
