    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    //
    // With our Buffer layout, A[i][j] is A_param(j, i).
    Func mvt_x1("mvt_x1");
    // Pure definition: initial x1.
    mvt_x1(i) = x1_param(i);
    // Update definition: accumulate over j.
    mvt_x1(i) += A_param(j_dom, i) * y1_param(j_dom);

    // Second kernel:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // A[j][i] is A_param(i, j) with our layout.
    Func mvt_x2("mvt_x2");
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, j_dom) * y2_param(j_dom);

    // JIT-compile the kernels once.
    mvt_x1.compile_jit();
    mvt_x2.compile_jit();

    // Time the execution of both kernels, similar to gemm.cpp.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernels: results are written back into x1 and x2 buffers.
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the results (similar in spirit to PolyBench print_array).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }

        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print execution time in seconds, with 6 decimal places.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
