    Func init_x1("init_x1"), init_x2("init_x2");
    Func init_y1("init_y1"), init_y2("init_y2");
    Func init_A("init_A");

    // n is a C++ int, but can be used directly in Expr arithmetic
    Expr n_expr = n;

    // C initialization:
    // x1[i] = (DATA_TYPE) (i % n) / n;
    // x2[i] = (DATA_TYPE) ((i + 1) % n) / n;
    // y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
    // y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
    init_x1(i) = cast<num_t>(i % n) / cast<num_t>(n_expr);
    init_x2(i) = cast<num_t>((i + 1) % n) / cast<num_t>(n_expr);
    init_y1(i) = cast<num_t>((i + 3) % n) / cast<num_t>(n_expr);
    init_y2(i) = cast<num_t>((i + 4) % n) / cast<num_t>(n_expr);

    // C initialization:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     A[i][j] = (DATA_TYPE) (i*j % n) / n;
    //
    // Array A is declared as A[i][j] in C, which we map to a Buffer
    // with shape (j, i) => A(j, i) in Halide.
    init_A(j, i) = cast<num_t>((i * j) % n) / cast<num_t>(n_expr);

    // Realize into the provided Buffers.
    init_x1.realize(x1);
    init_x2.realize(x2);
