int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[N][N];
    //   DATA_TYPE x1[N], x2[N], y_1[N], y_2[N];
    //
    // Following the array-to-Buffer mapping rule, A(i,j) in C is
    // represented as A_buf(j, i) in Halide. Since N == N here, the
    // shape is (n, n), but conceptually the first dim is column, second is row.
    Halide::Buffer<num_t, 2> A(n, n);   // A(j, i) corresponds to C's A[i][j]
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // Initialize data
    init_array(n, x1, x2, y_1, y_2, A);

    // -----------------------------------------------------------------
    // Halide representation of kernel_mvt
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Semantically:
    //   x1_out[i] = x1_in[i] + sum_j A[i][j] * y_1[j];
    //   x2_out[i] = x2_in[i] + sum_j A[j][i] * y_2[j];
    //
    // We express these as reductions over j (RDom), using the initial
    // x1, x2, A, y_1, y_2 as ImageParams.
    // -----------------------------------------------------------------

    ImageParam A_param(type_of<num_t>(), 2, "A_param");      // dims: (j, i)
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Bind Buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    Var i("i");
    // RDom over the first dimension of A (columns / j index)
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // x1_out[i] = x1_in[i] + sum_j A[i][j] * y_1[j]
    //
    // Mapping C A[i][j] -> A_param(j, i) (Buf dims: (j, i)).
    //
    // So in Halide:
    //   sum_j A_param(r, i) * y1_param(r)
    mvt_x1(i) = x1_param(i) + sum(A_param(r, i) * y1_param(r));

    // x2_out[i] = x2_in[i] + sum_j A[j][i] * y_2[j]
    //
    // Mapping C A[j][i] -> A_param(i, j) (Buf dims: (j, i)).
    //
    // So in Halide:
    //   sum_j A_param(i, r) * y2_param(r)
    mvt_x2(i) = x2_param(i) + sum(A_param(i, r) * y2_param(r));

    // The default schedule for these reductions already matches the
    // simple nested loops (outer i, inner r), so no explicit schedule
    // is strictly necessary. We could add simple reorders if desired,
    // but we keep it minimal to mirror the original structure.

    // Compile the kernels to machine code (JIT)
    mvt_x1.compile_jit();
    mvt_x2.compile_jit();

    // -----------------------------------------------------------------
    // Run the Halide kernels and measure execution time
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Realize results back into x1 and x2 Buffers. This overwrites
    // the initial contents, just like the original C kernel updates
    // the arrays in-place.
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench's print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        std::cerr << "x1:\n";
        for (int idx = 0; idx < n; idx++) {
